"""Build crawlable service, coverage and IT buyer resources. Run from repository root."""
from pathlib import Path
from html import escape
import json
from site_theme import ARTICLE_IMAGES

BASE = 'https://e2erecycling.com/'
DATE = '2026-10-28'
PAGES = []

def link(path, text):
    return f'<a href="{escape(path)}">{escape(text)}</a>'

def section(title, body):
    return f'<section><h2>{title}</h2>{body}</section>'

def bullets(items):
    return '<ul>' + ''.join(f'<li>{x}</li>' for x in items) + '</ul>'

def table(head, rows):
    return '<div class="table-wrap" tabindex="0" role="region" aria-label="Comparison table"><table><thead><tr>' + ''.join(f'<th scope="col">{x}</th>' for x in head) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{x}</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table></div>'

def add(slug, title, description, h1, intro, body, faqs, kind='service', related=None):
    PAGES.append(dict(slug=slug, title=title, description=description, h1=h1, intro=intro, body=body, faqs=faqs, kind=kind, related=related or []))

